"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7657],{73925:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainFuelGuiController","desc":"Drives the authored `TrainFuelGui` HUD without issuing any additional\\nnetwork packets. On every `RenderStepped` frame it extrapolates the current\\nfuel level from the last `Signals.OnTrainStateChanged` snapshot using the\\ndrain rate and elapsed server time, then eases the displayed bar value\\ntoward that prediction with frame-rate-independent exponential smoothing so\\nrefuel jumps animate smoothly. The fuel bar color reflects running, braked,\\nor stalled state.","realm":["Client"],"source":{"line":15,"path":"src/StarterPlayer/StarterPlayerScripts/TrainFuelGuiController.client.luau"}}')}}]);